# Studio with a fake microphone (Chromium test device: a beep, not a voice) + denied mic + upload route.
import asyncio,os,json
from playwright.async_api import async_playwright
async def st(pg,expr):return await pg.evaluate(expr)
async def main():
  async with async_playwright() as p:
    R={}
    # ---- A: microphone allowed (fake device) ----
    b=await p.chromium.launch(args=['--autoplay-policy=no-user-gesture-required','--use-fake-device-for-media-stream','--use-fake-ui-for-media-stream'])
    pg=await b.new_page(viewport={'width':1366,'height':900});errs=[];pg.on('pageerror',lambda e:errs.append(str(e)))
    await pg.goto('file://'+os.path.abspath('t2.html'));await pg.wait_for_timeout(400)
    await pg.click('#engines [data-e=vemmo]');await pg.click('#addVoice');await pg.wait_for_timeout(200)
    R['prep']=await st(pg,"({toRecDisabled:document.getElementById('toRecord').disabled,calc:document.getElementById('recCalc').textContent,sum:document.getElementById('recSum').textContent,script:document.getElementById('setScript').value,scriptHidden:document.getElementById('scriptList').hidden,uploadVisible:!document.getElementById('altRoute').hidden})")
    await pg.click('#micAsk');await pg.wait_for_timeout(1500)
    R['micAllowed']=await st(pg,"({state:document.getElementById('micState').textContent,meter:!document.getElementById('micMeterRow').hidden,lit:document.querySelectorAll('#meter1 i.on').length,levelTxt:document.getElementById('micLevelTxt').textContent,toRecDisabled:document.getElementById('toRecord').disabled})")
    await pg.screenshot(path='shot_prep.png',full_page=True)
    # practice: nothing recorded
    await pg.click('#practice');await pg.wait_for_timeout(200);await pg.click('#recStart');await pg.wait_for_timeout(2500)
    R['practice']=await st(pg,"({status:document.getElementById('recStatTxt').textContent,meterShown:!document.getElementById('recMeterWrap').hidden,line:document.getElementById('recLine').textContent,cue:document.getElementById('cue').textContent})")
    await pg.click('#stopBtn');await pg.wait_for_timeout(300)
    R['afterPractice']=await st(pg,"({step:[...document.querySelectorAll('#stepper li')].findIndex(l=>l.classList.contains('cur'))+1,msg:document.getElementById('micState').textContent})")
    # record: 10 vemmo lines; record ~3 lines, pause, resume, redo, stop
    await pg.click('#micAsk') if await pg.is_visible('#micAsk') else None;await pg.wait_for_timeout(800)
    await pg.click('#toRecord');await pg.wait_for_timeout(200)
    R['readyNotRecording']=await st(pg,"document.getElementById('recStatTxt').textContent")
    await pg.click('#recStart');await pg.wait_for_timeout(2400)
    R['live1']=await st(pg,"({status:document.getElementById('recStatTxt').textContent,line:document.getElementById('recLine').textContent,cue:document.getElementById('cue').textContent,meter:!document.getElementById('recMeterWrap').hidden,remain:document.getElementById('premain').textContent,back:document.getElementById('stBack').textContent})")
    await pg.screenshot(path='shot_rec.png',full_page=True)
    await pg.wait_for_timeout(9000)
    R['live2']=await st(pg,"({line:document.getElementById('recLine').textContent,cue:document.getElementById('cue').textContent})")
    await pg.click('#pauseBtn');await pg.wait_for_timeout(1200)
    R['paused']=await st(pg,"({status:document.getElementById('recStatTxt').textContent,btn:document.getElementById('pauseBtn').textContent,hint:document.getElementById('recHint').textContent})")
    await pg.click('#pauseBtn');await pg.wait_for_timeout(600);await pg.click('#redoBtn');await pg.wait_for_timeout(5500)
    R['afterResumeRedo']=await st(pg,"({status:document.getElementById('recStatTxt').textContent,line:document.getElementById('recLine').textContent})")
    await pg.click('#stopBtn');await pg.wait_for_timeout(2500)
    R['check']=await st(pg,"({partial:document.getElementById('partialNote').textContent.slice(0,60),dur:document.getElementById('recDur').textContent,lines:[...document.querySelectorAll('#lineList .ls')].map(x=>x.textContent).join('|'),missingBtn:!document.getElementById('recMissing').hidden,err:document.getElementById('procErr').hidden?'':document.getElementById('procErr').textContent})")
    await pg.click('#recPlay');await pg.wait_for_timeout(700);R['recPlayBtn']=await st(pg,"document.getElementById('recPlay').textContent");await pg.click('#recPlay')
    await pg.click('#prevPlay');await pg.wait_for_timeout(1200)
    R['preview']=await st(pg,"({text:document.getElementById('prevText').textContent,dur:document.getElementById('prevDur').textContent,engine:document.getElementById('prevEngine').value})")
    await pg.evaluate("document.getElementById('dLines').open=true");await pg.screenshot(path='shot_check.png',full_page=True)
    await pg.fill('#voiceName','Test voice');await pg.click('#saveVoice');await pg.wait_for_timeout(800)
    R['afterSave']=await st(pg,"({view:document.getElementById('viewMake').hidden?'other':'make',voice:document.getElementById('voiceSel').value,note:document.getElementById('voiceNote').textContent,msg:document.getElementById('voiceMsg').textContent,txt:document.getElementById('txt').value.slice(0,30),err:document.getElementById('saveErr').textContent})")
    await pg.click('#genBtn' if await pg.is_visible('#genBtn') else '#varBtn');await pg.wait_for_timeout(1500)
    R['genOwn']=await st(pg,"({meta:document.getElementById('resMeta').textContent,dur:document.getElementById('dur').textContent})")
    await pg.click('#navVoices');await pg.wait_for_timeout(300)
    R['voices']=await st(pg,"({rows:document.querySelectorAll('.vrow').length,first:document.querySelector('.vrow')?.textContent.slice(0,80),note:document.getElementById('storeNote').textContent})")
    await pg.screenshot(path='shot_voices.png',full_page=True)
    await pg.reload();await pg.wait_for_timeout(800);await pg.click('#navVoices');await pg.wait_for_timeout(300)
    R['voicesAfterReload']=await st(pg,"document.querySelectorAll('.vrow').length")
    R['errorsA']=errs;await b.close()
    # ---- B: microphone denied + upload route ----
    b=await p.chromium.launch(args=['--autoplay-policy=no-user-gesture-required'])
    ctxb=await b.new_context(viewport={'width':1366,'height':900});pg=await ctxb.new_page();errs=[];pg.on('pageerror',lambda e:errs.append(str(e)))
    await pg.goto('file://'+os.path.abspath('t2.html'));await pg.wait_for_timeout(300)
    await pg.click('#addVoice');await pg.click('#micAsk');await pg.wait_for_timeout(1500)
    R['denied']=await st(pg,"({state:document.getElementById('micState').textContent.slice(0,70),toRec:document.getElementById('toRecord').disabled,meter:!document.getElementById('micMeterRow').hidden})")
    await pg.click('#prompterOnly');await pg.click('#recStart');await pg.wait_for_timeout(2600)
    R['guide']=await st(pg,"({status:document.getElementById('recStatTxt').textContent,meter:!document.getElementById('recMeterWrap').hidden,recDot:document.getElementById('recStat').className})")
    await pg.click('#stopBtn');await pg.wait_for_timeout(300)
    R['guideEnd']=await st(pg,"({upload:!document.getElementById('upBox').hidden})")
    await pg.set_input_files('#file','vemmo_script_test.wav');await pg.wait_for_timeout(4000)
    R['upload']=await st(pg,"({body:!document.getElementById('checkBody').hidden,partial:document.getElementById('partialNote').hidden?'':document.getElementById('partialNote').textContent.slice(0,50),lines:document.querySelectorAll('#lineList li').length,ok:document.querySelectorAll('#lineList .ls.ok').length,dur:document.getElementById('recDur').textContent,err:document.getElementById('procErr').hidden?'':document.getElementById('procErr').textContent})")
    await pg.select_option('#prevEngine','vemmo');await pg.click('#prevPlay');await pg.wait_for_timeout(1000)
    R['uploadPreview']=await st(pg,"document.getElementById('prevText').textContent")
    await pg.click('#stBack');await pg.wait_for_timeout(300)
    R['leaveConfirm']=await st(pg,"({open:document.getElementById('cfDlg').open,title:document.getElementById('cfTitle').textContent})")
    await pg.click('#cfNo');R['stillStudio']=await st(pg,"!document.getElementById('viewStudio').hidden")
    # narrow viewport
    await pg.click('#stBack');await pg.click('#cfYes');await pg.set_viewport_size({'width':390,'height':844});await pg.wait_for_timeout(300)
    R['narrow']=await st(pg,"({scrollW:document.documentElement.scrollWidth,order:['pStyle','pText','pResult'].map(id=>Math.round(document.getElementById(id).getBoundingClientRect().top)),side:Math.round(document.querySelector('.col-side').getBoundingClientRect().top)})")
    await pg.screenshot(path='shot_narrow.png',full_page=True)
    await pg.set_viewport_size({'width':1280,'height':720});await pg.wait_for_timeout(200)
    R['laptop']=await st(pg,"({scrollW:document.documentElement.scrollWidth,genTop:Math.round(document.getElementById('genBtn').getBoundingClientRect().top)})")
    R['errorsB']=errs;await b.close()
    print(json.dumps(R,indent=1,ensure_ascii=False))
asyncio.run(main())
